<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,useId} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowLeft,MessageCircle,Heart,Plus,Download,Trash2,Search} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import AssetLinks from '../media/AssetLinks.vue'
import LibraryPortrait from '../presentation/LibraryPortrait.vue'
import CompanionWorldPanel from './CompanionWorldPanel.vue'
import {useAssetIndex} from '../media/asset-index'
import {videoDraft} from '../media/video-runtime'
import {composeMedia} from '../media/compose'
import type {Document} from '../domain/local-contract'
import {emptyCard,writeCard} from '../tavern/card-format'
import type {ChatSession} from '../tavern/chat-contract'
import {stopExecution} from '../task-runtime/active'
import {publishRevocation} from '../task-runtime/revocation'
import {styles,relationshipScore,appendRelationship,type CompanionProfile,type CompanionMemory,type Relationship} from './contract'
useAssetIndex()
const mediaLifecycle=new AbortController();let disposed=false
onUnmounted(()=>{disposed=true;mediaLifecycle.abort()})
const store=useLocal(),route=useRoute(),router=useRouter(),id=String(route.params.companionId),profile=ref<Document<CompanionProfile>|null>(null),memories=ref<Document<CompanionMemory>[]>([]),relationship=ref<Document<Relationship>|null>(null),error=ref(''),loading=ref(true),busy=ref(false),editing=ref(false),memoryText=ref(''),memoryEdit=ref<Document<CompanionMemory>|null>(null),anniversary=ref({title:'',date:''}),gift=ref({label:'一束花',amount:20})
const tab=ref<'profile'|'memory'|'records'|'world'>('profile'),tabs=[{id:'profile',label:'资料'},{id:'memory',label:'记忆'},{id:'records',label:'记录'},{id:'world',label:'世界'}] as const,tabId=useId(),memorySearch=ref(''),memoryFilter=ref<'active'|'retired'|'all'>('active')
const visibleMemories=computed(()=>memories.value.filter(row=>(memoryFilter.value==='all'||row.value.status===memoryFilter.value)&&row.value.text.toLocaleLowerCase().includes(memorySearch.value.trim().toLocaleLowerCase())))
function tabKey(event:KeyboardEvent){const index=tabs.findIndex(item=>item.id===tab.value),next=event.key==='ArrowRight'?(index+1)%tabs.length:event.key==='ArrowLeft'?(index+tabs.length-1)%tabs.length:event.key==='Home'?0:event.key==='End'?tabs.length-1:-1;if(next<0)return;event.preventDefault();tab.value=tabs[next]!.id;document.getElementById(tabId+'-tab-'+tab.value)?.focus()}
const form=ref({name:'',personality:'',style:'gentle' as CompanionProfile['style'],userName:'我',userDescription:''}),score=computed(()=>relationship.value?relationshipScore(relationship.value.value):{familiarity:0,sharedDays:0}),days=computed(()=>{const events=relationship.value?.value.events||[];return Array.from({length:28},(_,index)=>{const date=new Date();date.setDate(date.getDate()-27+index);const key=date.toISOString().slice(0,10);return {key,count:events.filter(event=>event.at.slice(0,10)===key).length}})})
async function load(){const vault=store.vault;if(!vault)return;profile.value=await vault.read<CompanionProfile>(id);if(!profile.value||profile.value.kind!=='companion')throw new Error('找不到这位伴侣');memories.value=(await vault.list<CompanionMemory>('memory')).filter(row=>row.value.companionId===id);relationship.value=await vault.read<Relationship>('relationship:'+id)}
async function companionMotion(){const vault=store.vault,row=profile.value;if(!vault||!row)return;try{const destination=await videoDraft(vault,'',{targetId:row.id,targetKind:'companion',targetRevision:row.revision,role:'attachment'},null,mediaLifecycle.signal);if(!disposed&&store.vault===vault&&vault.unlocked)await router.push(destination)}catch(e){if(!disposed)error.value=(e as Error).message}}
async function companionPicture(){const vault=store.vault,row=profile.value;if(!vault||!row)return;try{const destination=await composeMedia(vault,{signal:mediaLifecycle.signal,prompt:row.value.personality,source:{targetId:row.id,targetKind:'companion',targetRevision:row.revision,role:'portrait'}});if(!disposed&&store.vault===vault&&vault.unlocked)await router.push(destination)}catch(e){error.value=(e as Error).message}}
function edit(){const value=profile.value!.value;form.value={name:value.name,personality:value.personality,style:value.style,userName:value.user?.name||'我',userDescription:value.user?.description||''};editing.value=true}
async function saveProfile(){const vault=store.vault,row=profile.value;if(!vault||!row||busy.value)return;busy.value=true;try{await vault.commit(crypto.randomUUID(),'companion',id,row.revision,{...row.value,name:form.value.name.trim(),personality:form.value.personality,style:form.value.style,user:{name:form.value.userName.trim(),description:form.value.userDescription}});editing.value=false;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function chat(){const vault=store.vault,row=profile.value;if(!vault||!row||row.value.deleted||busy.value)return;busy.value=true;try{let sessionId=row.value.sessionId;if(!sessionId){sessionId=crypto.randomUUID();const card=emptyCard();card.identityId=row.value.identityId;card.name=row.value.name;card.personality=row.value.personality;const at=new Date().toISOString(),session:ChatSession={title:card.name,cards:[{id:'companion-card:'+id,revision:row.revision,value:card}],messageIds:[],persona:row.value.user||{name:'我',description:''},mode:'roleplay',authorNote:'',modelOverride:row.value.modelOverride||null,archived:false,parent:null,createdAt:at,currentTaskId:null,companionId:id};await vault.commitBundle('migrate-companion-session:'+id,[{kind:'companion',id,expectedRevision:row.revision,value:{...row.value,sessionId,proactiveEnabled:false}},{kind:'session',id:sessionId,expectedRevision:0,value:session}])}await router.push('/local/chat/'+sessionId)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function saveMemory(){const vault=store.vault;if(!vault||!memoryText.value.trim()||busy.value)return;busy.value=true;try{const at=new Date().toISOString(),prior=memoryEdit.value,value:CompanionMemory=prior?{...prior.value,text:memoryText.value.trim(),status:'active'}:{companionId:id,text:memoryText.value.trim(),status:'active',source:{kind:'user',text:memoryText.value.trim(),at},createdAt:at};await vault.commit(crypto.randomUUID(),'memory',prior?.id||crypto.randomUUID(),prior?.revision||0,value);memoryText.value='';memoryEdit.value=null;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function retire(row:Document<CompanionMemory>){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{await vault.commit(crypto.randomUUID(),'memory',row.id,row.revision,{...row.value,status:row.value.status==='active'?'retired':'active'});await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function record(kind:'gift'|'anniversary'){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{const row=relationship.value,value:Relationship=row?.value||{companionId:id,algorithm:'shared-events-v1',events:[],wallet:1000,anniversaries:[]},at=new Date().toISOString(),eventId=crypto.randomUUID();let next:Relationship;if(kind==='gift'){if(!Number.isSafeInteger(gift.value.amount)||gift.value.amount<1||gift.value.amount>value.wallet)throw new Error('叙事余额不足或数量无效');next=appendRelationship({...value,wallet:value.wallet-gift.value.amount},{id:eventId,type:'gift',at,sourceId:eventId,label:gift.value.label.trim(),amount:gift.value.amount})}else{if(!anniversary.value.title.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(anniversary.value.date))throw new Error('请填写纪念日');next=appendRelationship({...value,anniversaries:[...value.anniversaries,{id:eventId,...anniversary.value}]},{id:eventId,type:'anniversary',at,sourceId:eventId,label:anniversary.value.title});anniversary.value={title:'',date:''}}await vault.commit('relationship-action:'+eventId,'relationship','relationship:'+id,row?.revision||0,next);await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function exportCard(){if(!profile.value)return;const card=emptyCard();card.identityId=profile.value.value.identityId;card.name=profile.value.value.name;card.personality=profile.value.value.personality;card.description=memories.value.filter(row=>row.value.status==='active').map(row=>row.value.text).join('\n');const url=URL.createObjectURL(new Blob([writeCard(card)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=card.name+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function remove(){const vault=store.vault,row=profile.value;if(!vault||!row||busy.value)return;busy.value=true;try{const sessions=(await vault.list<ChatSession>('session')).filter(chat=>chat.value.companionId===id);for(const session of sessions)if(session.value.currentTaskId)stopExecution(vault,session.value.currentTaskId);await vault.commitBundle(crypto.randomUUID(),[{kind:'companion',id,expectedRevision:row.revision,value:{...row.value,deleted:true,proactiveEnabled:false}},...sessions.map(session=>({kind:'session' as const,id:session.id,expectedRevision:session.revision,value:{...session.value,archived:true}}))]);publishRevocation(vault.id,sessions.map(session=>session.id));await router.push('/local/companions')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(async()=>{try{await load()}catch(e){error.value=(e as Error).message}finally{loading.value=false}})
</script>
<template><section class="companion-workspace"><div class="final-page-heading"><RouterLink class="final-icon-button" to="/local/companions" aria-label="返回伴侣"><ArrowLeft :size="22"/></RouterLink><div class="final-heading-copy"><h1 :title="profile?.value.name">{{profile?.value.name||'伴侣'}}</h1></div><button v-if="profile&&!profile.value.deleted" class="final-primary" :disabled="busy" @click="chat"><MessageCircle :size="18"/>聊一会儿</button></div><p v-if="loading" role="status">正在打开…</p><p v-if="error" class="final-error" role="alert">{{error}}</p><p v-if="profile?.value.deleted">这份伴侣档案已归档。</p><template v-else-if="profile"><div class="companion-profile-hero"><LibraryPortrait :document="profile" :name="profile.value.name"/><div><span>{{styles[profile.value.style]}}</span><p>{{profile.value.personality||'从今天的一次对话开始。'}}</p><small>{{score.familiarity}} 次交谈 · {{score.sharedDays}} 天共同记录</small></div></div><nav class="companion-profile-tabs" role="tablist" aria-label="伴侣档案"><button v-for="item in tabs" :id="tabId+'-tab-'+item.id" :key="item.id" role="tab" :aria-selected="tab===item.id" :aria-controls="tabId+'-panel-'+item.id" :tabindex="tab===item.id?0:-1" @click="tab=item.id" @keydown="tabKey">{{item.label}}</button></nav><div v-show="tab==='profile'" :id="tabId+'-panel-profile'" role="tabpanel" :aria-labelledby="tabId+'-tab-profile'" class="companion-panel profile-panel"><section class="final-setting-card"><AssetLinks :target-id="profile.id" target-kind="companion" :target-revision="profile.revision" role="portrait"/><h2>相处与形象</h2><button @click="edit">编辑资料</button><button @click="companionPicture">绘制形象</button><button @click="companionMotion">动态照片</button><form v-if="editing" class="final-card-form" @submit.prevent="saveProfile"><label>名字<input v-model="form.name" maxlength="200" required></label><label>人格<textarea v-model="form.personality" maxlength="20000"></textarea></label><label>相处风格<select v-model="form.style"><option v-for="(label,key) in styles" :key="key" :value="key">{{label}}</option></select></label><label>你的名字<input v-model="form.userName" required maxlength="200"></label><label>关于你<textarea v-model="form.userDescription" maxlength="12000"></textarea></label><button class="final-primary" :disabled="busy">保存资料</button></form></section><section class="final-setting-card"><h2>档案</h2><RouterLink v-if="profile.value.promotion?.source.kind==='session'" class="final-text-link" :to="'/local/chat/'+profile.value.promotion.source.id">回到原聊天</RouterLink><RouterLink v-if="profile.value.sourceCard" class="final-text-link" :to="{path:'/local/characters',query:{card:profile.value.sourceCard.id}}">查看原角色</RouterLink><button @click="exportCard"><Download :size="18"/>导出标准角色卡</button><details><summary>归档伴侣</summary><p class="final-subtle">停止这位伴侣的会话，保留已有档案和请求记录。</p><button :disabled="busy" @click="remove"><Trash2 :size="18"/>确认归档</button></details></section></div><div v-show="tab==='memory'" :id="tabId+'-panel-memory'" role="tabpanel" :aria-labelledby="tabId+'-tab-memory'" class="companion-panel memory-panel"><section class="final-setting-card"><h2>记得的事</h2><form class="final-card-form" @submit.prevent="saveMemory"><label>{{memoryEdit?'纠正记忆':'添加记忆'}}<textarea v-model="memoryText" maxlength="8000" required></textarea></label><button class="final-primary" :disabled="busy"><Plus :size="18"/>{{memoryEdit?'保存纠正':'记住'}}</button></form><div class="memory-find"><label><Search :size="17"/><input v-model="memorySearch" type="search" aria-label="搜索伴侣记忆" placeholder="寻找记得的事" maxlength="200"></label><select v-model="memoryFilter" aria-label="记忆状态"><option value="active">正在使用</option><option value="retired">已停用</option><option value="all">全部</option></select></div><p v-if="!visibleMemories.length" class="final-subtle">{{memorySearch?'没有找到这条记忆':memoryFilter==='retired'?'没有停用的记忆':'从一件想让 TA 记住的事开始。'}}</p><article v-for="row in visibleMemories" :key="row.id" class="final-memory" :class="{'is-retired':row.value.status==='retired'}"><p>{{row.value.text}}</p><details><summary>来源原文</summary><p>{{row.value.source.text}}</p><small>{{new Date(row.value.source.at).toLocaleString()}}</small></details><div class="final-grid-actions"><button :disabled="busy" @click="memoryEdit=row;memoryText=row.value.text">纠正</button><button :disabled="busy" @click="retire(row)">{{row.value.status==='active'?'不再使用':'恢复记忆'}}</button></div></article></section></div><div v-show="tab==='records'" :id="tabId+'-panel-records'" role="tabpanel" :aria-labelledby="tabId+'-tab-records'" class="companion-panel records-panel"><section class="final-setting-card"><h2>纪念日</h2><form class="final-card-form" @submit.prevent="record('anniversary')"><label>纪念什么<input v-model="anniversary.title" maxlength="120" required></label><label>日期<input v-model="anniversary.date" type="date" required></label><button :disabled="busy">保存纪念日</button></form><p v-for="day in relationship?.value.anniversaries" :key="day.id">{{day.date}} · {{day.title}}</p></section><section class="final-setting-card"><h2>故事里的礼物</h2><p class="final-subtle">叙事余额 {{relationship?.value.wallet??1000}} · 仅用于虚构互动</p><form class="final-card-form" @submit.prevent="record('gift')"><label>礼物<input v-model="gift.label" maxlength="120" required></label><label>叙事金额<input v-model.number="gift.amount" type="number" min="1" step="1" required></label><button :disabled="busy">送出礼物</button></form></section><section class="final-setting-card"><h2>共同记录</h2><div class="final-heatmap" aria-label="最近28天互动"><span v-for="day in days" :key="day.key" :class="{'has-events':day.count>0}" :title="day.key+' · '+day.count+' 条真实记录'"></span></div><p v-if="!relationship?.value.events.length" class="final-subtle">还没有共同记录</p><p v-for="event in relationship?.value.events.slice(-30).reverse()" :key="event.id"><time>{{new Date(event.at).toLocaleDateString()}}</time> · {{event.label}}</p></section></div><div v-show="tab==='world'" :id="tabId+'-panel-world'" role="tabpanel" :aria-labelledby="tabId+'-tab-world'" class="companion-panel"><CompanionWorldPanel :profile="profile" @saved="profile=$event"/></div></template></section></template>

<style scoped>
.companion-workspace{max-width:1120px}.companion-workspace .final-page-heading{align-items:center}.companion-workspace .final-page-heading>div.final-heading-copy{min-width:0;flex:1}.companion-workspace .final-heading-copy h1{font-size:32px;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.companion-workspace summary{display:flex;align-items:center;min-height:44px;cursor:pointer}.companion-workspace .final-page-heading>button{white-space:nowrap;min-height:44px}.companion-profile-hero{display:flex;gap:28px;align-items:center;margin:0 0 32px}.companion-profile-hero :deep(.character-portrait){width:128px;flex:none;aspect-ratio:3/4;border-radius:12px}.companion-profile-hero>div{display:grid;gap:14px;min-width:0;max-width:720px}.companion-profile-hero span,.companion-profile-hero small{color:var(--quiet);font-size:13px}.companion-profile-hero p{font-family:var(--font-serif);font-size:20px;line-height:1.8;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden}.companion-profile-tabs{display:flex;gap:8px;border-bottom:1px solid var(--edge);margin-bottom:28px}.companion-profile-tabs button{display:flex;align-items:center;justify-content:center;gap:8px;min-height:48px;min-width:80px;padding:10px 18px;border:0;border-bottom:2px solid transparent;border-radius:0;background:transparent;color:var(--quiet)}.companion-profile-tabs button[aria-selected=true]{border-color:var(--accent);color:var(--accent)}.companion-profile-tabs small{font-size:12px}.companion-panel{display:grid;gap:32px}.profile-panel,.records-panel{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.records-panel>section:last-child{grid-column:1/-1}.memory-panel{max-width:840px}.companion-workspace .final-setting-card{padding:0;border:0;border-radius:0;background:transparent;min-width:0;align-content:start}.companion-workspace .final-card-form{padding:18px;background:var(--canvas);border-radius:12px;max-width:none;gap:16px}.memory-find{display:flex;gap:12px;align-items:center}.memory-find label{position:relative;flex:1;min-width:0}.memory-find svg{position:absolute;top:16px;left:14px;color:var(--quiet)}.memory-find input{padding-left:42px}.memory-find select{width:130px;min-width:110px}.final-memory{padding:18px 0;border-bottom:1px solid var(--edge)}.final-memory p{white-space:pre-wrap;overflow-wrap:anywhere}.final-memory details{margin-top:12px;color:var(--quiet)}.final-memory .final-grid-actions{margin-top:12px;flex-wrap:wrap}.final-memory.is-retired{opacity:.65}
@media(max-width:600px){.companion-workspace .final-heading-copy h1{font-size:26px}.companion-workspace .final-page-heading{gap:12px;flex-wrap:nowrap}.companion-workspace .final-page-heading>button{padding:10px 12px;font-size:14px}.companion-profile-hero{gap:20px;margin-bottom:24px;align-items:start}.companion-profile-hero :deep(.character-portrait){width:90px}.companion-profile-hero p{font-size:17px;-webkit-line-clamp:4}.companion-profile-hero>div{gap:10px}.profile-panel,.records-panel{grid-template-columns:1fr}.companion-profile-tabs{margin-bottom:24px}.companion-profile-tabs{gap:4px}.companion-profile-tabs button{flex:1;min-width:0;padding:10px 6px;overflow-wrap:anywhere}.memory-find{gap:8px}.memory-find select{width:110px}.companion-workspace .final-card-form{padding:16px}}
</style>
